using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");

    [McpServerTool, Description("Echoes back the provided message with a timestamp.")]
    public static string Echo(
        [Description("The message to echo back")] string message) =>
        $"[{DateTime.UtcNow:HH:mm:ss}] {message}";
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ServerResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(new
        {
            version = "1.0.0",
            environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            features = new { logging = true, caching = false }
        }, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(UriTemplate = "config://limits/{tier}", Name = "Rate Limits",
        MimeType = "application/json"),
     Description("Returns rate limit configuration for the specified tier.")]
    public static string GetRateLimits(
        [Description("The tier to get limits for (free, pro, enterprise)")] string tier) =>
        JsonSerializer.Serialize(tier.ToLowerInvariant() switch
        {
            "free"       => new { requestsPerMinute = 10,  maxPayloadKb = 256 },
            "pro"        => new { requestsPerMinute = 100, maxPayloadKb = 1024 },
            "enterprise" => new { requestsPerMinute = 1000, maxPayloadKb = 10240 },
            _            => new { requestsPerMinute = 0,   maxPayloadKb = 0 }
        }, new JsonSerializerOptions { WriteIndented = true });
}

